CREATE TABLE batch_tracked_models(model_id TEXT PRIMARY KEY, canonical_slug TEXT NOT NULL, publisher_prefix TEXT NOT NULL, first_seen_at_utc TEXT NOT NULL, tracking_state TEXT NOT NULL DEFAULT 'active', manual_reason TEXT);
CREATE TABLE batch_ranking_snapshots(snapshot_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES collection_runs(run_id), collection_date TEXT NOT NULL, window_start TEXT NOT NULL, window_end TEXT NOT NULL, source_as_of TEXT NOT NULL, ranking_retrieval_id TEXT NOT NULL REFERENCES raw_retrievals(retrieval_id), catalog_retrieval_id TEXT NOT NULL REFERENCES raw_retrievals(retrieval_id));
CREATE TABLE batch_ranking_entries(snapshot_id TEXT NOT NULL REFERENCES batch_ranking_snapshots(snapshot_id), rank INTEGER NOT NULL, model_id TEXT NOT NULL, canonical_slug TEXT NOT NULL, total_tokens_text TEXT NOT NULL, publisher_allowed INTEGER NOT NULL, PRIMARY KEY(snapshot_id,model_id));
CREATE TABLE batch_endpoint_polls(poll_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES collection_runs(run_id), model_id TEXT NOT NULL REFERENCES batch_tracked_models(model_id), retrieval_id TEXT REFERENCES raw_retrievals(retrieval_id), attempted_at_utc TEXT NOT NULL, outcome TEXT NOT NULL CHECK(outcome IN ('success','empty','http_error','parse_error','network_error')), listed_count INTEGER);
CREATE TABLE batch_endpoint_observations(poll_id TEXT NOT NULL REFERENCES batch_endpoint_polls(poll_id), model_id TEXT NOT NULL, polled_at_utc TEXT NOT NULL, provider_name TEXT NOT NULL, endpoint_tag TEXT NOT NULL, status_json TEXT, pricing_json TEXT, raw_endpoint_json TEXT NOT NULL, PRIMARY KEY(poll_id,provider_name,endpoint_tag));
CREATE INDEX batch_observations_history ON batch_endpoint_observations(model_id,polled_at_utc,provider_name,endpoint_tag);
CREATE TABLE batch_discovery_reviews(value TEXT NOT NULL, reason TEXT NOT NULL, first_seen_at_utc TEXT NOT NULL, last_seen_at_utc TEXT NOT NULL, PRIMARY KEY(value,reason));
